/// <summary>
/// Dialog builder for Utilitas data collection
/// </summary>
internal final class NDXUtilitasUIBuilder extends SysOperationAutomaticUIBuilder
{
    NDXUtilitasDataOpContract utilitasDataOpContract;
    DialogField dlgfAll, dlgfItemId, dlgfComp;


}

Method.Source:
public void build()
{
    super();
    utilitasDataOpContract = this.dataContractObject() as NDXUtilitasDataOpContract;

    dlgfItemId = this.bindInfo().getDialogField(utilitasDataOpContract, methodStr(NDXUtilitasDataOpContract , parmItemId));
    dlgfAll = this.bindInfo().getDialogField(utilitasDataOpContract, methodStr(NDXUtilitasDataOpContract , parmAllCatalogItems));
    dlgfComp = this.bindInfo().getDialogField(utilitasDataOpContract, methodStr(NDXUtilitasDataOpContract ,parmCompanies));

    dlgfAll.registerOverrideMethod(methodStr(FormCheckBoxControl, modified), methodStr(NDXUtilitasUIBuilder, dlgfAll_modified), this);
}

public void postRun()
{
    FormCheckBoxControl fchkbc;
    super();

    fchkbc = dlgfAll.control();
    this.dlgfAll_modified(fchkbc);
}

/// <summary>
/// Modified
/// </summary>
/// <param name = "_control">control</param>
/// <returns>true or false</returns>
public boolean dlgfAll_modified(FormCheckBoxControl  _control)
{
    boolean ret = _control.modified();

    dlgfItemId.enabled(!_control.checked());
    dlgfComp.enabled(_control.checked());

    return ret;
}
